window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[352]={"id":"352","numero":352,"titre":"Crise d'angoisse aiguë & Attaque de panique","objectifs":[{"id":"352-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la crise d’angoisse et de l’attaque de panique","contenu":"<p>La <span class=\"kw-etio\">crise d'angoisse aiguë</span> et l'<span class=\"kw-etio\">attaque de panique</span> (AP) désignent <strong>une seule et même entité diagnostique</strong> : « attaque de panique » est le terme de la nomenclature internationale (DSM-5), « crise d'angoisse » le terme clinique francophone classique.</p>\n      <p>L'AP se définit comme un <strong>épisode aigu d'<span class=\"kw-clinique\">anxiété</span></strong>, <strong>bien délimité dans le temps</strong> : début <strong>brutal</strong>, intensité maximale (<span class=\"kw-def\">acmé</span>) atteinte en <span class=\"kw-chiffre\">moins de 10 minutes</span>, puis résolution progressive.</p>\n      <div class=\"callout callout-info\"><strong>Piège de vocabulaire.</strong> « Crise d'angoisse aiguë » et « attaque de panique » sont strictement synonymes — un QCM qui <span class=\"kw-clinique\">les</span> oppose comme deux entités distinctes est faux.</div>","frequence":0},{"id":"352-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence et les âges concernés","contenu":"<p>L'attaque de panique est un <strong>tableau clinique très fréquent</strong>, notamment dans <span class=\"kw-clinique\">les</span> services d'<span class=\"kw-alerte\">urgence</span> où ses symptômes physiques bruyants sont au premier plan.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Donnée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Prévalence</span> vie entière</td><td><span class=\"kw-chiffre\">3-5 %</span> de la population générale — environ <strong>1 personne sur 20</strong> fera une AP au cours de sa vie</td></tr>\n          <tr><td><span class=\"kw-def\">Terrain</span> typique</td><td>Adulte jeune, avec <strong>prédominance féminine</strong> : <span class=\"kw-chiffre\">2 femmes pour 1 homme</span></td></tr>\n          <tr><td>Pic à l'adolescence</td><td><span class=\"kw-chiffre\">2,5 %</span> chez <span class=\"kw-clinique\">les</span> filles ; <span class=\"kw-chiffre\">2 %</span> chez les garçons</td></tr>\n          <tr><td>Enfance</td><td>AP <strong>rares</strong> avant l'adolescence : <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">&lt; 1 %</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"352-3","rang":"B","rubrique":"Etiologie","titre":"Connaître les facteurs de risque et mécanismes psychophysiologiques","contenu":"<p>La <span class=\"kw-def\">physiopathologie de l'attaque de panique</span> reste <strong>mal connue</strong>. Plusieurs mécanismes psychophysiologiques convergent.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Hypocapnie</span> par hyperventilation</td><td>L'<span class=\"kw-clinique\">hyperventilation</span> entraîne une hypocapnie qui explique une partie des symptômes : <span class=\"kw-clinique\">sensations vertigineuses</span>, <span class=\"kw-clinique\">paresthésies</span></td></tr>\n          <tr><td>Facteurs <span class=\"kw-etio\">biologiques</span></td><td>Dysfonctionnement de la régulation de certains neurotransmetteurs ; la <span class=\"kw-etio\">cholécystokinine</span> et le <span class=\"kw-etio\">lactate de sodium</span> sont capables de provoquer de véritables AP</td></tr>\n          <tr><td>Facteurs <span class=\"kw-etio\">psychologiques</span></td><td><span class=\"kw-def\">Auto-renforcement des cognitions catastrophistes</span> : <span class=\"kw-clinique\">les</span> symptômes physiques alimentent l'interprétation catastrophiste, qui aggrave en retour les symptômes</td></tr>\n          <tr><td>Facteurs <span class=\"kw-etio\">environnementaux</span></td><td>L'<strong>inquiétude de l'entourage</strong> renforce <span class=\"kw-clinique\">les</span> cognitions catastrophistes du patient</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Facteurs de risque</span>.</strong> La fiche source ne détaille pas de liste de facteurs de risque spécifiques au-delà du <strong><span class=\"kw-def\">terrain</span></strong> : <span class=\"kw-clinique\">sexe féminin</span> et <strong>âge jeune</strong> (adulte jeune, pic à l'adolescence) sont <span class=\"kw-clinique\">les</span> principaux facteurs prédisposants connus.</p>","frequence":0},{"id":"352-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de diagnostic d’une attaque de panique","contenu":"<p>Le diagnostic d'attaque de panique est <strong>clinique</strong> : l'interrogatoire du patient et de son <strong>entourage</strong> (souvent très informatif) suffit.</p>\n      <p><strong>Installation et cinétique.</strong> Apparition <strong>brutale</strong> des symptômes, atteignant leur <span class=\"kw-def\">acmé</span> en <span class=\"kw-chiffre\">moins de 10 minutes</span>. Le DSM-5 distingue deux types d'AP :</p>\n      <ul>\n        <li><strong>AP attendues / prévisibles / réactionnelles</strong> — déclenchées par un facteur identifiable (ex. exposition brutale à un stimulus phobogène)</li>\n        <li><strong>AP inattendues / imprévisibles</strong> — survenant <strong>sans facteur déclenchant</strong>, plus spécifiques du <span class=\"kw-etio\">trouble panique</span></li>\n      </ul>\n      <p><strong>Critères DSM-5.</strong> L'AP est une période bien délimitée de crainte ou de <span class=\"kw-clinique\">malaise</span> intense, dans laquelle <strong><span class=\"kw-chiffre\">≥ 4 des 13 symptômes</span></strong> suivants surviennent de façon brutale et atteignent leur acmé en <span class=\"kw-chiffre\">&lt; 10 minutes</span>, répartis en <strong>6 familles</strong> :</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Symptômes</th></tr></thead>\n        <tbody>\n          <tr><td>Respiratoire</td><td><span class=\"kw-clinique\">Souffle coupé</span> ou impression d'étouffement ; <span class=\"kw-clinique\">sensation d'étranglement</span></td></tr>\n          <tr><td>Cardiaque</td><td><span class=\"kw-clinique\">Palpitations</span> ou accélération du rythme cardiaque ; <span class=\"kw-clinique\">douleur ou gêne thoracique</span></td></tr>\n          <tr><td>Neurovégétative</td><td><span class=\"kw-clinique\">Transpiration</span> ; <span class=\"kw-clinique\">frissons</span> ou bouffées de chaleur ; <span class=\"kw-clinique\">vertige</span>, instabilité, tête vide ou impression d'évanouissement</td></tr>\n          <tr><td>Digestive</td><td><span class=\"kw-clinique\">Nausée</span> ou gêne abdominale</td></tr>\n          <tr><td>Neurologique</td><td><span class=\"kw-clinique\">Tremblements</span> ou secousses musculaires ; <span class=\"kw-clinique\">paresthésies</span> (engourdissement, picotements)</td></tr>\n          <tr><td>Psychique</td><td><span class=\"kw-clinique\">Peur de perdre le contrôle</span> ou de devenir fou ; <span class=\"kw-clinique\">peur de mourir</span> ; <span class=\"kw-clinique\">déréalisation</span> (sentiment d'irréalité) ou <span class=\"kw-clinique\">dépersonnalisation</span> (être détaché de soi)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Symptômes psychiques au premier plan.</strong> Peur intense, volontiers <strong>sans objet identifiable</strong> (sensation de catastrophe imminente) et sensation de perte de contrôle. <span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">cognitions catastrophistes</span> sont centrées sur deux thèmes : « peur de mourir » et « peur de devenir fou ». Des symptômes dissociatifs peuvent s'associer : <span class=\"kw-clinique\">dépersonnalisation</span> et <span class=\"kw-clinique\">déréalisation</span>.</p>\n      <p><strong>Symptômes comportementaux.</strong> Comportement variable d'un patient à l'autre, allant de l'<span class=\"kw-clinique\">agitation psychomotrice</span> à la <span class=\"kw-clinique\">prostration</span>.</p>\n      <div class=\"callout callout-danger\"><strong>Complication grave.</strong> La principale complication, rare mais grave, est le <span class=\"kw-alerte\">passage à l'acte auto-agressif</span> pendant la crise — à rechercher systématiquement.</div>\n      <div class=\"callout callout-warn\"><strong>Pièges QCM (correction Paris).</strong> La <strong>déréalisation</strong> / le « sentiment d'irréalité » EST un critère DSM-5. <span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">hallucinations olfactives</span> ne sont PAS un critère (distracteur fréquent). C'est le <strong>début</strong> qui est brutal, <strong>pas la fin</strong> : « disparition brutale des symptômes » est compté faux.</div>","frequence":2},{"id":"352-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les diagnostics différentiels psychiatriques et non psychiatriques","contenu":"<div class=\"callout callout-danger\"><strong>Règle absolue.</strong> L'attaque de panique est un <span class=\"kw-alerte\">diagnostic d'élimination</span>. Ses symptômes physiques imposent un <strong>examen clinique complet, appareil par appareil</strong>, complété si besoin d'examens paracliniques orientés (<span class=\"kw-bio\">ECG</span>, <span class=\"kw-imagerie\">radiographie thoracique</span>, <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">troponine</span>).</div>\n      <p><strong>1 · Diagnostics différentiels non psychiatriques.</strong> <span class=\"kw-clinique\">Les</span> symptômes physiques étant au premier plan, il faut éliminer une cause organique :</p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Causes à éliminer</th></tr></thead>\n        <tbody>\n          <tr><td>Respiratoire</td><td><span class=\"kw-etio\">Asthme</span> ; <span class=\"kw-alerte\">embolie pulmonaire</span> ; <span class=\"kw-etio\">pneumopathie</span></td></tr>\n          <tr><td>Cardiovasculaire</td><td><span class=\"kw-alerte\">Syndrome coronarien aigu</span> ; <span class=\"kw-clinique\">poussée</span> d'<span class=\"kw-etio\">insuffisance cardiaque</span> ; <span class=\"kw-alerte\">dissection aortique</span> ; <span class=\"kw-etio\">HTA</span> ; <span class=\"kw-etio\">troubles du rythme</span></td></tr>\n          <tr><td>Neurologique</td><td><span class=\"kw-etio\">Épilepsie</span> (notamment crises partielles temporales) ; crises <span class=\"kw-etio\">migraineuses</span> ; <span class=\"kw-etio\">AIT</span></td></tr>\n          <tr><td>Endocrinien</td><td><span class=\"kw-clinique\">Hypoglycémie</span> ; <span class=\"kw-etio\">phéochromocytome</span> ; <span class=\"kw-etio\">hyperthyroïdie</span> ; syndrome de <span class=\"kw-etio\">Cushing</span> ; <span class=\"kw-etio\">hypoparathyroïdie</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Causes toxiques et iatrogènes</strong> — à distinguer : ce sont plus des <strong>éléments déclencheurs</strong> de l'AP que de véritables diagnostics différentiels :</p>\n      <ul>\n        <li><strong>Intoxications aiguës</strong> par substance psychoactive : <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">cannabis</span>, <span class=\"kw-etio\">cocaïne</span>, <span class=\"kw-etio\">ecstasy</span></li>\n        <li><strong>Causes iatrogènes</strong> : <span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">hormones thyroïdiennes</span> — favorisent <span class=\"kw-clinique\">les</span> AP en cas de surdosage</li>\n        <li><strong>Contexte de <span class=\"kw-ttt\">sevrage</span></strong> à rechercher : <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">benzodiazépines</span></li>\n      </ul>\n      <p><strong>2 · Diagnostics différentiels psychiatriques — cadre de survenue.</strong> Une AP peut être <strong>isolée</strong> (épisode unique, le plus souvent réactionnel à un stress, pouvant survenir hors de tout trouble psychiatrique) ou survenir dans le cadre d'un trouble psychiatrique :</p>\n      <table >\n        <thead><tr><th>Cadre</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Trouble panique</span></td><td>Répétition d'AP <strong>imprévisibles</strong> (sans facteur déclenchant), <span class=\"kw-clinique\">anxiété anticipatoire</span>, ± <span class=\"kw-clinique\">agoraphobie</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Phobie</span> (simple ou sociale)</td><td>AP déclenchée par la confrontation à une situation <strong>phobogène</strong></td></tr>\n          <tr><td><span class=\"kw-etio\">TSPT</span></td><td>AP déclenchée par la confrontation à une situation évocatrice d'un <strong>traumatisme</strong></td></tr>\n          <tr><td><span class=\"kw-etio\">TAG</span></td><td>AP survenant à l'acmé de <span class=\"kw-clinique\">ruminations anxieuses</span></td></tr>\n          <tr><td><span class=\"kw-etio\">EDC</span></td><td>AP survenant à l'acmé de <span class=\"kw-clinique\">ruminations dépressives</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-etio\">AVC</span> · 151 — <span class=\"kw-etio\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span> · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 66 — Trouble anxieux</em></p>","frequence":0},{"id":"352-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prise en charge de l’attaque de panique en aigu","contenu":"<p>Une fois le diagnostic d'attaque de panique retenu, la prise en charge en aigu repose <strong>d'abord</strong> sur des mesures non pharmacologiques.</p>\n      <p><strong>1 · Mesures non pharmacologiques</strong> — <span class=\"kw-chiffre\">première intention</span>, suffisent le plus souvent :</p>\n      <ul>\n        <li><strong>Mise en condition</strong> : installation au calme, suppression des éléments anxiogènes, <span class=\"kw-def\">isolement</span> relatif, <strong>attitude empathique</strong></li>\n        <li><strong>Réassurance</strong> du patient :\n          <ul>\n            <li>Délivrer le <span class=\"kw-def\">diagnostic positif</span> : « il s'agit d'une attaque de panique »</li>\n            <li>Informer sur l'<span class=\"kw-alerte\">absence de danger de mort</span> et sur le caractère <strong>spontanément résolutif</strong> de l'AP</li>\n            <li>Reconnaître la <strong>souffrance subjective</strong> du patient : <span class=\"kw-clinique\">les</span> symptômes sont réels et particulièrement désagréables</li>\n          </ul>\n        </li>\n        <li><strong>Mesures de contrôle respiratoire</strong> : allongement du temps d'expiration, au mieux à <strong>lèvres pincées</strong> — cela stimule le <span class=\"kw-clinique\">tonus vagal</span>, focalise l'attention du patient et limite l'<span class=\"kw-clinique\">hyperventilation</span></li>\n      </ul>\n      <p><strong>2 · Traitement pharmacologique</strong> — uniquement <strong>si l'AP se prolonge</strong> :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Benzodiazépine per os</span> = référence ; la voie parentérale n'apporte <strong>aucun avantage</strong> pharmacocinétique</li>\n        <li>Traitement <strong>ponctuel</strong>, dans le contexte de l'<span class=\"kw-alerte\">urgence</span> : <span class=\"kw-ci\">à ne pas prescrire au long cours</span> (risque de <span class=\"kw-alerte\">dépendance</span>)</li>\n        <li>Alternative possible : <span class=\"kw-ttt\">hydroxyzine</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Le traitement pharmacologique n'est <strong>pas systématique</strong> : il est réservé aux AP qui se prolongent malgré <span class=\"kw-clinique\">les</span> mesures non pharmacologiques. Délivrer le <span class=\"kw-def\">diagnostic positif</span>, rassurer et faire contrôler la respiration suffit dans la majorité des cas.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble anxieux</em></p>","frequence":0},{"id":"352-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge à distance de l’attaque de panique","contenu":"<p>La prise en charge à distance dépend du <strong>cadre de survenue</strong> de l'attaque de panique.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Prise en charge</th></tr></thead>\n        <tbody>\n          <tr><td><strong>AP isolée</strong></td><td><span class=\"kw-clinique\">Éducation thérapeutique</span> : <span class=\"kw-ttt\">règles hygiéno-diététiques</span> simples pour prévenir une récidive, et apprentissage de la reconnaissance d'une récidive</td></tr>\n          <tr><td><strong>AP dans le cadre d'un trouble psychiatrique</strong></td><td>Prise en charge du <span class=\"kw-def\">trouble psychiatrique sous-jacent</span> (trouble panique, phobie, TSPT, TAG, EDC)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble anxieux</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> l'<span class=\"kw-etio\">attaque de panique</span> est <span class=\"kw-def\">spontanément résolutive</span> et sans danger vital, mais elle reste un <span class=\"kw-etio\">diagnostic d'élimination</span> en contexte d'urgence.<br><strong>Fenêtre :</strong> apparition <span class=\"kw-clinique\">brutale</span> des symptômes, atteignant leur <span class=\"kw-def\">acmé</span> en <span class=\"kw-chiffre\">moins de 10 minutes</span> puis régression.<br><strong>1er geste :</strong> <span class=\"kw-clinique\">examen clinique complet appareil par appareil</span> pour éliminer une <span class=\"kw-alerte\">urgence non psychiatrique</span> (<span class=\"kw-etio\">SCA</span>, <span class=\"kw-etio\">embolie pulmonaire</span>, <span class=\"kw-etio\">dissection aortique</span>, <span class=\"kw-etio\">hypoglycémie</span>).</p>","hospit":"<p><strong>Le plus souvent :</strong> prise en charge <span class=\"kw-ttt\">aux urgences</span> ou en <span class=\"kw-ttt\">ambulatoire</span>, avec retour à domicile après <span class=\"kw-ttt\">réassurance</span> et résolution de la crise.<br><strong>AP isolée :</strong> orientation vers une <span class=\"kw-ttt\">éducation thérapeutique</span> (prévenir et reconnaître une récidive).<br><strong>AP dans un trouble psychiatrique :</strong> orientation vers la <span class=\"kw-ttt\">prise en charge du trouble sous-jacent</span> (<span class=\"kw-etio\">trouble panique</span>, <span class=\"kw-etio\">phobie</span>, <span class=\"kw-etio\">TSPT</span>, <span class=\"kw-etio\">TAG</span>, <span class=\"kw-etio\">EDC</span>).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Passage à l'acte auto-agressif</span> : principale complication, <span class=\"kw-alerte\">rare mais grave</span>, à rechercher systématiquement</li><li><span class=\"kw-clinique\">Douleur ou gêne thoracique</span> : éliminer un <span class=\"kw-etio\">syndrome coronarien aigu</span> ou une <span class=\"kw-etio\">dissection aortique</span></li><li><span class=\"kw-clinique\">Dyspnée</span> / <span class=\"kw-clinique\">sensation d'étouffement</span> : éliminer une <span class=\"kw-etio\">embolie pulmonaire</span>, un <span class=\"kw-etio\">asthme</span>, une <span class=\"kw-etio\">pneumopathie</span></li><li><span class=\"kw-clinique\">Hallucinations olfactives</span> : n'évoquent PAS une attaque de panique, doivent faire rechercher une autre <span class=\"kw-etio\">étiologie</span> (ex. <span class=\"kw-etio\">épilepsie temporale</span>)</li><li>Contexte d'<span class=\"kw-etio\">intoxication</span> (cocaïne, cannabis, ecstasy), de <span class=\"kw-etio\">sevrage</span> (<span class=\"kw-etio\">alcool</span>, <span class=\"kw-ttt\">benzodiazépines</span>) ou de cause <span class=\"kw-etio\">iatrogène</span> (<span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">hormones thyroïdiennes</span>)</li></ul>","principes":"<p>La prise en charge en aigu est avant tout <span class=\"kw-ttt\">non pharmacologique</span> ; le traitement <span class=\"kw-ttt\">anxiolytique</span> n'est ajouté que si la crise se prolonge.</p><p><strong>Mesures non pharmacologiques (1re intention)</strong></p><ul><li><span class=\"kw-ttt\">Mise en condition</span> : installation au calme, <span class=\"kw-def\">isolement</span>, suppression des éléments anxiogènes, attitude empathique</li><li><span class=\"kw-ttt\">Réassurance</span> : délivrer un <span class=\"kw-ttt\">diagnostic positif</span> (« il s'agit d'une attaque de panique »), informer sur l'<span class=\"kw-def\">absence de danger de mort</span> et le caractère <span class=\"kw-def\">spontanément résolutif</span></li><li>Reconnaître la <span class=\"kw-clinique\">souffrance subjective</span> du patient : <span class=\"kw-clinique\">les</span> symptômes sont réels et désagréables</li><li><span class=\"kw-ttt\">Contrôle respiratoire</span> : allongement du temps d'expiration à lèvres pincées (stimule le <span class=\"kw-def\">tonus vagal</span>, limite l'<span class=\"kw-clinique\">hyperventilation</span>)</li></ul><p><strong>Traitement pharmacologique (si l'AP se prolonge)</strong></p><p>Anxiolytique uniquement si l'attaque de panique se prolonge, jamais en systématique.</p><ul><li><span class=\"kw-ttt\">Benzodiazépine per os</span> = référence (la voie parentérale n'apporte aucun avantage pharmacocinétique)</li><li>Alternative : <span class=\"kw-ttt\">hydroxyzine</span></li><li>Traitement <span class=\"kw-chiffre\">ponctuel</span> de l'<span class=\"kw-alerte\">urgence</span> : <span class=\"kw-ci\">ne doit pas être prescrit au long cours</span> (risque de <span class=\"kw-etio\">dépendance</span>)</li></ul><p><strong>Prise en charge à distance</strong></p><ul><li><span class=\"kw-etio\">AP isolée</span> : <span class=\"kw-ttt\">éducation thérapeutique</span> (<span class=\"kw-ttt\">RHD</span> simples pour prévenir et reconnaître une récidive)</li><li><span class=\"kw-etio\">AP dans un trouble psychiatrique</span> : <span class=\"kw-ttt\">prise en charge du trouble sous-jacent</span></li></ul>","suivi":"<p><strong>En aigu :</strong> surveiller la <span class=\"kw-clinique\">résolution spontanée</span> de la crise (acmé puis régression) et l'<span class=\"kw-alerte\">absence de passage à l'acte auto-agressif</span>.<br><strong>À distance :</strong> rechercher une <span class=\"kw-etio\">récidive</span> et un <span class=\"kw-etio\">trouble psychiatrique sous-jacent</span> (<span class=\"kw-etio\">trouble panique</span>, <span class=\"kw-etio\">phobie</span>, <span class=\"kw-etio\">TSPT</span>, <span class=\"kw-etio\">TAG</span>, <span class=\"kw-etio\">EDC</span>) à prendre en charge.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Crise aiguë d'angoisse avec symptômes physiques au 1er plan — Apparition brutale, acmé en moins de 10 minutes","detail":"<h4>CAT — Suspicion d'attaque de panique aux urgences — Du tableau aigu d'angoisse à la prise en charge</h4>","branches":[{"to":"q-organique","label":"Évaluation initiale","color":"blue"}]},{"id":"q-organique","kind":"decision","label":"Examen clinique complet : argument pour une urgence non psychiatrique ? — Diagnostic d'élimination avant de retenir l'attaque de panique","branches":[{"to":"t-organique","label":"Oui","color":"red"},{"to":"q-criteres","label":"Non","color":"green"}]},{"id":"t-organique","kind":"terminal","label":"Prise en charge de l'urgence somatique","color":"red","detail":"<h4>Clinique</h4><ul><li>Point d'appel <span class=\"kw-etio\">respiratoire</span> (<span class=\"kw-etio\">asthme</span>, <span class=\"kw-etio\">embolie pulmonaire</span>, <span class=\"kw-etio\">pneumopathie</span>), <span class=\"kw-etio\">cardiovasculaire</span> (<span class=\"kw-etio\">SCA</span>, <span class=\"kw-etio\">dissection aortique</span>, <span class=\"kw-etio\">trouble du rythme</span>), <span class=\"kw-etio\">neurologique</span> (<span class=\"kw-etio\">épilepsie temporale</span>, <span class=\"kw-etio\">AIT</span>) ou <span class=\"kw-etio\">endocrinien</span> (<span class=\"kw-etio\">hypoglycémie</span>, <span class=\"kw-etio\">phéochromocytome</span>, <span class=\"kw-etio\">hyperthyroïdie</span>)</li></ul><h4>Paraclinique</h4><ul><li>Examens orientés selon le point d'appel : <span class=\"kw-imagerie\">ECG</span>, <span class=\"kw-imagerie\">radiographie thoracique</span>, <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">troponine</span></li></ul><h4>Conduite</h4><ul><li>Traiter en priorité l'<span class=\"kw-alerte\">urgence non psychiatrique</span> identifiée ; l'<span class=\"kw-etio\">attaque de panique</span> reste un <span class=\"kw-etio\">diagnostic d'élimination</span></li></ul>"},{"id":"q-criteres","kind":"decision","label":"Critères d'attaque de panique réunis ? — <span class=\"kw-chiffre\">≥ 4</span> des 13 symptômes, début brutal, acmé < <span class=\"kw-chiffre\">10 min</span>","branches":[{"to":"t-reeval","label":"Non","color":"blue"},{"to":"q-prolonge","label":"Oui","color":"green"}]},{"id":"t-reeval","kind":"terminal","label":"Reconsidérer le diagnostic","color":"blue","detail":"<h4>Conduite</h4><ul><li>Moins de <span class=\"kw-chiffre\">4 symptômes</span> ou tableau atypique : reconsidérer <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">diagnostics différentiels</span> psychiatriques (<span class=\"kw-etio\">phobie</span>, <span class=\"kw-etio\">TSPT</span>, <span class=\"kw-etio\">TAG</span>, <span class=\"kw-etio\">EDC</span>) et non psychiatriques, et compléter le bilan si besoin</li></ul>"},{"id":"q-prolonge","kind":"decision","label":"Sous mesures non pharmacologiques, la crise se prolonge ? — Réassurance + contrôle respiratoire appliqués","branches":[{"to":"t-resolution","label":"Non — résolution","color":"green"},{"to":"t-pharmaco","label":"Oui — crise prolongée","color":"amber"}]},{"id":"t-resolution","kind":"terminal","label":"Résolution spontanée → retour à domicile — AP spontanément résolutive","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Réassurance</span> et <span class=\"kw-ttt\">contrôle respiratoire</span> ont suffi : <span class=\"kw-def\">résolution spontanée</span> de la crise, retour à domicile</li></ul><h4><span class=\"kw-def\">Suivi</span></h4><ul><li><span class=\"kw-etio\">AP isolée</span> : <span class=\"kw-ttt\">éducation thérapeutique</span> (prévenir et reconnaître une récidive)</li><li><span class=\"kw-etio\">AP dans un trouble psychiatrique</span> : <span class=\"kw-ttt\">prise en charge du trouble sous-jacent</span></li></ul>"},{"id":"t-pharmaco","kind":"terminal","label":"Anxiolytique ponctuel — Crise prolongée malgré les mesures non pharmacologiques","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Benzodiazépine per os</span> = référence (voie parentérale sans avantage pharmacocinétique) ; alternative : <span class=\"kw-ttt\">hydroxyzine</span></li></ul><h4>Conduite</h4><ul><li>Traitement <span class=\"kw-chiffre\">ponctuel</span> de l'<span class=\"kw-alerte\">urgence</span> : <span class=\"kw-ci\">pas de prescription au long cours</span> (risque de <span class=\"kw-etio\">dépendance</span>)</li></ul><h4><span class=\"kw-def\">Suivi</span></h4><ul><li>Puis <span class=\"kw-ttt\">prise en charge à distance</span> selon le contexte (<span class=\"kw-etio\">AP isolée</span> → <span class=\"kw-def\">éducation thérapeutique</span> ; <span class=\"kw-etio\">trouble psychiatrique</span> → PEC du trouble)</li></ul>"}]},"cards":[{"i":"378ecda22109","n":352,"o":"352-1","u":"Définition","t":"Connaître la définition de la crise d’angoisse et de l’attaque de panique","q":"Quelle est la relation entre les termes \"crise d'angoisse aiguë\" et \"attaque de panique\" selon la nomenclature médicale ?","a":"<p>Ces deux termes désignent une <strong>seule et même entité diagnostique</strong>. « Attaque de panique » est le terme de la nomenclature internationale (DSM-5), tandis que « crise d'angoisse aiguë » est le terme clinique francophone classique.</p>"},{"i":"d101fa5ed67b","n":352,"o":"352-1","u":"Définition","t":"Connaître la définition de la crise d’angoisse et de l’attaque de panique","q":"Le terme \"crise d'angoisse aiguë\" désigne-t-il une entité distincte de l'\"attaque de panique\" ?","a":"<p>Non, les termes « crise d'angoisse aiguë » et « attaque de panique » sont <strong>strictement synonymes</strong> et désignent la même entité diagnostique. Il est faux de les opposer comme deux entités distinctes.</p>"},{"i":"f82d7a2d3e3e","n":352,"o":"352-1","u":"Définition","t":"Connaître la définition de la crise d’angoisse et de l’attaque de panique","q":"Comment définir une attaque de panique ?","a":"<p>L'attaque de panique est un épisode aigu d'<strong>anxiété</strong>, bien délimité dans le temps, caractérisé par :</p><ul><li>Un <strong>début brutal</strong>.</li><li>Une intensité maximale (<strong>acmé</strong>) atteinte en <strong>moins de 10 minutes</strong>.</li><li>Une résolution progressive.</li></ul>"},{"i":"130b37ea4476","n":352,"o":"352-4","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une attaque de panique","q":"Les hallucinations olfactives sont-elles un critère DSM-5 de l'attaque de panique ?","a":"<p>Non, les <strong>hallucinations olfactives ne sont PAS un critère</strong> DSM-5 de l'attaque de panique.</p>"},{"i":"14b53fc56435","n":352,"o":"352-4","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une attaque de panique","q":"Quels sont les symptômes psychiques les plus fréquemment mis en avant lors d'une attaque de panique ?","a":"<ul><li><strong>Peur de mourir</strong></li><li><strong>Peur de perdre le contrôle ou de devenir fou</strong></li><li><strong>Sensation de catastrophe imminente</strong></li><li><strong>Déréalisation</strong> (sentiment d'irréalité)</li><li><strong>Dépersonnalisation</strong> (être détaché de soi-même)</li></ul>"},{"i":"711677ce86ac","n":352,"o":"352-4","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une attaque de panique","q":"Quelle est la particularité symptomatique essentielle d'une attaque de panique selon le DSM-5 ?","a":"<p>Une attaque de panique est une période bien délimitée de crainte ou de malaise intense, durant laquelle <strong>au moins 4 des 13 symptômes</strong> caractéristiques surviennent de façon brutale et atteignent leur acmé en moins de 10 minutes.</p>"},{"i":"74b990b68d97","n":352,"o":"352-4","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une attaque de panique","q":"Quels sont les deux types d'attaques de panique distingués par le DSM-5 ?","a":"<ul><li>Les attaques de panique <strong>attendues / prévisibles / réactionnelles</strong>, déclenchées par un facteur identifiable.</li><li>Les attaques de panique <strong>inattendues / imprévisibles</strong>, survenant sans facteur déclenchant, plus spécifiques du trouble panique.</li></ul>"},{"i":"96f369e38c51","n":352,"o":"352-4","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une attaque de panique","q":"Selon le DSM-5, quel est le délai d'apparition et d'acmé des symptômes d'une attaque de panique ?","a":"<p>Selon le DSM-5, les symptômes d'une attaque de panique apparaissent <strong>brutalement</strong> et atteignent leur <strong>acmé en moins de 10 minutes</strong>.</p>"},{"i":"b400a36be2a9","n":352,"o":"352-4","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une attaque de panique","q":"La déréalisation est-elle un critère DSM-5 de l'attaque de panique ?","a":"<p>Oui, la <strong>déréalisation</strong> (sentiment d'irréalité) EST un critère DSM-5 de l'attaque de panique.</p>"},{"i":"d2a83e4b3473","n":352,"o":"352-4","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une attaque de panique","q":"Quelle est la principale complication grave à rechercher systématiquement lors d'une attaque de panique ?","a":"<p>La principale complication grave d'une attaque de panique, bien que rare, est le <strong>passage à l'acte auto-agressif</strong> pendant la crise.</p>"},{"i":"ff467bb747ae","n":352,"o":"352-4","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une attaque de panique","q":"Comment le diagnostic d'une attaque de panique est-il établi ?","a":"<p>Le diagnostic d'une attaque de panique est <strong>clinique</strong>, reposant sur l'<strong>interrogatoire</strong> du patient et de son entourage.</p>"},{"i":"016d95fea3dd","n":352,"o":"352-5","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels psychiatriques et non psychiatriques","q":"Quelles sont les principales causes non psychiatriques cardiovasculaires à éliminer devant une attaque de panique ?","a":"<p>Les principales causes non psychiatriques cardiovasculaires à éliminer devant une attaque de panique sont :</p><ul><li>le <strong>syndrome coronarien aigu</strong> ;</li><li>une <strong>poussée d'insuffisance cardiaque</strong> ;</li><li>une <strong>dissection aortique</strong> ;</li><li>une <strong>HTA</strong> ;</li><li>des <strong>troubles du rythme</strong>.</li></ul>"},{"i":"34e44e058cef","n":352,"o":"352-5","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels psychiatriques et non psychiatriques","q":"Quelles sont les principales causes non psychiatriques neurologiques et endocriniennes à éliminer devant une attaque de panique ?","a":"<p>Les principales causes non psychiatriques à éliminer devant une attaque de panique sont :</p><ul><li><strong>Neurologiques</strong> : l'<strong>épilepsie</strong> (notamment crises partielles temporales), les <strong>crises migraineuses</strong>, l'<strong>AIT</strong>.</li><li><strong>Endocriniennes</strong> : l'<strong>hypoglycémie</strong>, le <strong>phéochromocytome</strong>, l'<strong>hyperthyroïdie</strong>, le <strong>syndrome de Cushing</strong>, l'<strong>hypoparathyroïdie</strong>.</li></ul>"},{"i":"4dd2b4e0c5a0","n":352,"o":"352-5","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels psychiatriques et non psychiatriques","q":"Quelle doit être la règle absolue face à une suspicion d'attaque de panique ?","a":"<p>Face à une suspicion d'attaque de panique, la règle absolue est que le diagnostic d'attaque de panique est un <strong>diagnostic d'élimination</strong>. Il impose un <strong>examen clinique complet</strong>, appareil par appareil, complété si besoin d'examens paracliniques orientés.</p>"},{"i":"99f021783958","n":352,"o":"352-5","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels psychiatriques et non psychiatriques","q":"Dans quels cadres psychiatriques les attaques de panique peuvent-elles survenir ?","a":"<p>Une attaque de panique peut être isolée ou survenir dans le cadre des troubles psychiatriques suivants :</p><ul><li><strong>Trouble panique</strong> : répétition d'AP imprévisibles, anxiété anticipatoire, ± agoraphobie.</li><li><strong>Phobie</strong> (simple ou sociale) : AP déclenchée par la confrontation à une situation phobogène.</li><li><strong>Trouble de Stress Post-Traumatique (TSPT)</strong> : AP déclenchée par la confrontation à une situation évocatrice d'un traumatisme.</li><li><strong>Trouble Anxieux Généralisé (TAG)</strong> : AP survenant à l'acmé de ruminations anxieuses.</li><li><strong>Épisode Dépressif Caractérisé (EDC)</strong> : AP survenant à l'acmé de ruminations dépressives.</li></ul>"},{"i":"f59e0264d2a3","n":352,"o":"352-5","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels psychiatriques et non psychiatriques","q":"Quelles sont les causes toxiques et iatrogènes pouvant déclencher une attaque de panique, à distinguer des véritables diagnostics différentiels ?","a":"<p>Les causes toxiques et iatrogènes pouvant déclencher une attaque de panique, et à distinguer des diagnostics différentiels, sont :</p><ul><li>Les <strong>intoxications aiguës par substance psychoactive</strong> : <strong>alcool</strong>, <strong>cannabis</strong>, <strong>cocaïne</strong>, <strong>ecstasy</strong>.</li><li>Les <strong>causes iatrogènes</strong> (en cas de surdosage) : <strong>corticoïdes</strong>, <strong>hormones thyroïdiennes</strong>.</li><li>Les <strong>contextes de sevrage</strong> : <strong>alcool</strong>, <strong>benzodiazépines</strong>.</li></ul>"},{"i":"d2d3950f668a","n":352,"o":"352-6","u":"Prise en charge","t":"Connaître la prise en charge de l’attaque de panique en aigu","q":"Quelle est la première étape de la prise en charge en aigu d'une attaque de panique ?","a":"<p>La première étape est la mise en œuvre de <strong>mesures non pharmacologiques</strong>.</p>"},{"i":"efb7f3026924","n":352,"o":"352-6","u":"Prise en charge","t":"Connaître la prise en charge de l’attaque de panique en aigu","q":"Quelles sont les mesures non pharmacologiques à mettre en place pour la prise en charge aiguë d'une attaque de panique ?","a":"<ul><li>Mise en condition: installation au calme, suppression des éléments anxiogènes, isolement relatif, attitude empathique.</li><li><strong>Réassurance</strong> du patient: délivrer le diagnostic positif, informer sur l'<strong>absence de danger de mort</strong> et le caractère spontanément résolutif de l'attaque de panique, reconnaître la souffrance subjective du patient.</li><li><strong>Mesures de contrôle respiratoire</strong>: allongement du temps d'expiration, au mieux à lèvres pincées, pour stimuler le tonus vagal et limiter l'hyperventilation.</li></ul>"},{"i":"f81d4a1a3cb7","n":352,"o":"352-6","u":"Prise en charge","t":"Connaître la prise en charge de l’attaque de panique en aigu","q":"Quand et comment initier un traitement pharmacologique pour une attaque de panique ?","a":"<p>Le traitement pharmacologique n'est indiqué <strong>uniquement si l'attaque de panique se prolonge malgré les mesures non pharmacologiques</strong>.</p><ul><li>La <strong>benzodiazépine per os</strong> est le traitement de référence, à utiliser de manière ponctuelle et non au long cours (risque de dépendance).</li><li>Une alternative possible est l'<strong>hydroxyzine</strong>.</li></ul>"}]};